WITH last_row AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY 仓库名称, 商品编号, 批号 ORDER BY CAST(按日期 AS DATE), id) AS rn
  FROM dbo.inout
), batch_bal AS (
  SELECT 仓库名称, 商品编号, 批号, 库存数量 FROM last_row WHERE rn=1
), prod_bal AS (
  SELECT 仓库名称, 商品编号, SUM(库存数量) AS 批次合计
  FROM batch_bal GROUP BY 仓库名称, 商品编号
), cur AS (
  SELECT 仓库名称, 商品编号, 现有库存 FROM dbo.inout WHERE 现有库存 IS NOT NULL
)
SELECT COUNT(*) AS 不一致组合数 FROM prod_bal p JOIN cur c ON p.仓库名称=c.仓库名称 AND p.商品编号=c.商品编号
WHERE ABS(p.批次合计 - c.现有库存) > 0.001
